mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM `COMMENT`
    WHERE COMMENT_ID = #{commentId}
        AND POST_ID = #{postId}
        AND PARENT_COMMENT_ID IS NULL
)

mapper.update:
UPDATE `COMMENT`
SET
    CONTENT = #{content},
    UPDATE_AT = NOW()
WHERE COMMENT_ID = #{commentId}
    AND USER_ID = #{userId}
